<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class macceptancelevelmodel extends CI_Model {    function fnGetAcceptlevelInfo($VarAcceptlevel = '', $VarStatus = '', $VarId = '') {        $this->db->select('id,acceptablelevel,updatedby,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_ACCEPTANCE_LEVEL);        // if ($VarStatus <> '') {        //     $this->db->where_in('status', array($VarStatus));        // } else {        //     $this->db->where_in('status', array(1, 2));        // }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarAcceptlevel <> '') {            $ArrWhere['acceptablelevel'] = trim($VarAcceptlevel);        }        if (!empty($ArrWhere)) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheck($VarData = '', $VarId = '') {        $this->db->from(KN_MASTER_ACCEPTANCE_LEVEL);        // $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['acceptablelevel'] = trim($VarData);        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveAcceptlevelInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetAcceptlevelInfo($ArrUpdateData['acceptablelevel'], 1);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_ACCEPTANCE_LEVEL, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This acceptance level already exists";            }        } else {            $VarAlreadyExists = $this->fnCheck($ArrUpdateData['acceptablelevel'], $VarId);            if (empty($VarAlreadyExists)) {                if ($this->db->update(KN_MASTER_ACCEPTANCE_LEVEL, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data!';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This acceptance level already exists";            }        }        return $ArrResult;    }    function fnCountAcceptlevel($VarLevel = '', $VarStatus = '', $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarCompanyId = $ArrUserLoggedInfo['companyid'];        $ArrWhere = array();        if ($VarLevel <> '') {            $ArrWhere[] = "al.acceptablelevel like '%$VarLevel%' ";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "al.acceptablelevel like '" . $VarAfilter . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "al.status=" . $VarStatus;        } else {            $ArrWhere[] = "al.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND al.companyid = '" . $VarCompanyId . "'";        }        $VarSqlLab = "SELECT count(1) as trec  FROM " . KN_MASTER_ACCEPTANCE_LEVEL . " AS al LEFT JOIN " . KN_USERS . " AS u ON al.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnListAcceptlevel($VarLevel = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder, $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarCompanyId = $ArrUserLoggedInfo['companyid'];        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('acceptablelevel', 'status', 'contactname', 'dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarAfilter <> '') {            $ArrWhere[] = "al.acceptablelevel like '" . $VarAfilter . "%'";        }        if ($VarLevel <> '') {            $ArrWhere[] = "al.acceptablelevel like '%$VarLevel%' ";        }        if ($VarStatus <> '') {            $ArrWhere[] = "al.status = " . $VarStatus;        } else {            $ArrWhere[] = "al.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND al.companyid = '" . $VarCompanyId . "'";        }         // removed this line in . " limit " . $VarLimitInfo  below query        $VarSqlLab = "SELECT al.id,al.acceptablelevel,al.dateupdated,contactname,al.status FROM " . KN_MASTER_ACCEPTANCE_LEVEL . " AS al LEFT JOIN " . KN_USERS . " AS u ON al.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder;        $ObjResult = $this->db->query($VarSqlLab);        return $ObjResult;    }    function changeStatus($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_ACCEPTANCE_LEVEL, array('status' => $optvalue))) {            return true;        }        return false;    }}